@push('scripts')<script>const products=@json($products),preselected=@json($preselected);const c=document.querySelector('[data-category]'),b=document.querySelector('[data-brand]'),p=document.querySelector('[data-product]'),v=document.querySelector('[data-variant]'),m=document.querySelector('[data-months]'),q=document.querySelector('[data-quote]');function emptyQuote(message='Choose an available variant to see your monthly payment.'){q.innerHTML=`<div class="flex items-center gap-2 text-sm font-bold text-blue-100"><span class="material-symbols-outlined">payments</span>YOUR INSTALLMENT ESTIMATE / قيمة القسط</div><p class="mt-4 text-sm text-blue-100">${message}</p>`}function fill(){let x=products.filter(x=>(!c.value||x.category_id==c.value)&&(!b.value||x.brand==b.value));p.innerHTML='<option value="">Select product</option>'+x.map(x=>`<option value="${x.id}">${x.name}</option>`).join('');v.innerHTML='<option value="">Select available variant</option>';emptyQuote()}function variants(){let x=products.find(x=>x.id==p.value);v.innerHTML='<option value="">Select available variant</option>'+(x?x.variants.map(y=>`<option value="${y.id}">${[...y.option_values.map(z=>z.display_name||z.name),y.sku].filter(Boolean).join(' · ')} — ${y.price}</option>`).join(''):'')}async function quote(){if(!p.value||!v.value)return;let r=await fetch('{{ route('installments.quote') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({product_id:p.value,variant_id:v.value,months:m.value})});let x=await r.json();if(!r.ok){emptyQuote(x.message||'Selected option is no longer available.');return}q.innerHTML=`<div class="flex items-center justify-between gap-3 text-sm font-bold text-blue-100"><span class="flex items-center gap-2"><span class="material-symbols-outlined">payments</span>YOUR MONTHLY PAYMENT</span><span class="rounded-full bg-white/15 px-3 py-1 text-xs">${m.value} months</span></div><div class="mt-4 flex items-end gap-2"><strong class="text-4xl tracking-tight">${x.monthly_payment}</strong><span class="mb-1 font-bold text-blue-100">${x.currency} / month</span></div><div class="mt-5 grid grid-cols-2 gap-px overflow-hidden rounded-xl bg-white/20 text-sm"><div class="bg-blue-950/20 p-3"><span class="block text-[11px] font-bold uppercase tracking-wide text-blue-100">Device price</span><strong class="mt-1 block">${x.product_price} ${x.currency}</strong></div><div class="bg-blue-950/20 p-3"><span class="block text-[11px] font-bold uppercase tracking-wide text-blue-100">Total payable</span><strong class="mt-1 block">${x.total_payable} ${x.currency}</strong></div></div>`}c.onchange=b.onchange=fill;p.onchange=variants;v.onchange=m.onchange=quote;const selectedProduct=products.find(product=>product.id===Number(preselected.product_id));if(selectedProduct){c.value=selectedProduct.category_id||'';b.value=selectedProduct.brand||'';fill();p.value=String(selectedProduct.id);variants();v.value=String(preselected.variant_id||'');m.value=String(preselected.installment_months||m.value);c.disabled=b.disabled=p.disabled=true;quote()}else{fill()}document.querySelectorAll('[data-upload-input]').forEach(input=>input.addEventListener('change',()=>{const name=document.querySelector(`[data-upload-name="${input.dataset.uploadInput}"]`);const card=document.querySelector(`[data-upload-card="${input.dataset.uploadInput}"] label`);if(name)name.textContent=input.files[0]?.name||'Choose file / اختر ملفاً';card?.classList.toggle('border-[var(--pm-primary)]',Boolean(input.files.length));card?.classList.toggle('bg-blue-50',Boolean(input.files.length))}));const identity=document.querySelector('[name="identity_document_type"]'),back=document.querySelector('[data-upload-input="id_back"]'),badge=document.querySelector('[data-upload-required="id_back"]');function passportState(){const passport=identity?.value==='lebanese_passport';back.required=!passport;if(badge)badge.textContent=passport?'Optional':'Required'}identity?.addEventListener('change',passportState);passportState()</script>@endpush
@push('scripts')
<script>
    // Keep the payment summary high-contrast after every selection change.
    function emptyQuote(message = 'Choose an available variant to see your monthly payment.') {
        q.innerHTML = `<div class="flex items-center gap-2 text-sm font-extrabold text-blue-700"><span class="material-symbols-outlined">payments</span>YOUR INSTALLMENT ESTIMATE / قيمة القسط</div><p class="mt-4 text-sm font-medium text-slate-700">${message}</p>`;
    }

    async function quote() {
        if (!p.value || !v.value) return;
        const response = await fetch('{{ route('installments.quote') }}', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json', 'X-CSRF-TOKEN': '{{ csrf_token() }}' }, body: JSON.stringify({ product_id: p.value, variant_id: v.value, months: m.value }) });
        const estimate = await response.json();
        if (!response.ok) return emptyQuote(estimate.message || 'Selected option is no longer available.');
        q.innerHTML = `<div class="flex items-center justify-between gap-3 text-sm font-extrabold text-blue-700"><span class="flex items-center gap-2"><span class="material-symbols-outlined">payments</span>YOUR MONTHLY PAYMENT</span><span class="rounded-full bg-blue-100 px-3 py-1 text-xs text-blue-800">${m.value} months</span></div><div class="mt-4 flex items-end gap-2"><strong class="text-4xl tracking-tight text-slate-950">${estimate.monthly_payment}</strong><span class="mb-1 font-bold text-slate-700">${estimate.currency} / month</span></div><div class="mt-5 grid grid-cols-2 gap-3 text-sm"><div class="rounded-xl bg-slate-100 p-3"><span class="block text-[11px] font-bold uppercase tracking-wide text-slate-600">Device price</span><strong class="mt-1 block text-slate-950">${estimate.product_price} ${estimate.currency}</strong></div><div class="rounded-xl bg-blue-50 p-3"><span class="block text-[11px] font-bold uppercase tracking-wide text-blue-700">Total payable</span><strong class="mt-1 block text-slate-950">${estimate.total_payable} ${estimate.currency}</strong></div></div>`;
    }

    c.onchange = b.onchange = fill;
    p.onchange = variants;
    v.onchange = m.onchange = quote;
    emptyQuote();
</script>
@endpush
